export function enZuDe(roh) {
  const s = norm(roh).toLowerCase().replace(/[.;]+$/, '').replace(/\b(high[- ]quality|premium|quality|soft|durable|environmentally friendly|eco[- ]friendly)\b/g, '').replace(/\s+/g, ' ').trim();
