  if (MISCH.test(t) && imTitel.length > 1) return !imTitel.every(r => r.test(w));   // Mischung im Titel: der Wert muss alle genannten Stoffe nennen
  return !imTitel.some(r => r.test(w));
}
/** Letzte Sperre vor dem Schreiben: Wert, der mehr verspricht, als die übrigen Quellen hergeben, bleibt weg. `uebersetzung`: nur die Sprache ändert sich, der Wert stand schon da. */
export function pruefeWert(wert, { descriptionHtml, titel, cj }, { uebersetzung = false } = {}) {
  if (TITANSTAHL.test(wert)) return '«Titanstahl» ist ein mehrdeutiger Handelsname, kein belegter Stoff';
  const cjText = [cj?.description, cj?.productProEn, cj?.productPro].filter(Boolean).join('\n');
  if (klammerKonflikt(descriptionHtml, wert) || klammerKonflikt(cjText, wert, CJ_ZEILE, enZuDe))
    return 'einschränkender Klammerzusatz widerspricht dem Stoffwert';
  if (/^pu$/i.test(wert) || /^pu,|, ?pu$/i.test(wert)) return 'alleinstehendes «PU» ist mehrdeutig (Polyurethan oder PU-Leder)';
