#!/usr/bin/env node
/**
 * Zählt den Arbeitsstand aus den Ledgern (nur lesen) und schreibt ihn als JSON-Zeilen für die Fortschrittsseite.
 * Aufruf: node automation/fortschritt_daten.mjs [OUT=/tmp/fortschritt.json]
 * Jede Zahl nennt ihre Quelle (Ledger-Datei). Fehlende/unlesbare Quellen ergeben null, nie 0 oder 100 %.
 * Ledger-Erfolge sind Arbeitsfortschritt, keine aktuelle Vollständigkeitsquote für Farbe, Grösse oder Material.
 */
import { readFileSync, writeFileSync } from 'node:fs';
const OUT = process.env.OUT || '/tmp/fortschritt.json';
const lesefehler = new Map();
const lies = p => {
  try { return readFileSync(p, 'utf8').split('\n').filter(z => z.trim()); }
  catch (e) { lesefehler.set(p, e.code || 'nicht lesbar'); return null; }
};
const unbekannt = (p, grund) => { lesefehler.set(p, grund); return null; };
const zeitpunkt = new Date().toISOString();

const geschrieben = ledger => {
  const zeilen = lies(ledger);
  if (zeilen === null) return null;
  const teile = zeilen.map(z => z.split('·').map(s => s.trim()));
  if (teile.some(([h, zeit, e]) => !h || !Number.isFinite(Date.parse(zeit)) || !e)) return unbekannt(ledger, 'ungültige Ledger-Zeile');
  return new Set(teile.filter(([, , e]) => e === 'GESCHRIEBEN').map(([h]) => h));
};
const kategorien = lies('dropship/kategorien_ledger.txt');
const art = k => kategorien === null ? null : new Set(kategorien.map(z => z.split(' · ')).filter(t => (t[1] || '').split(' ')[0] === k).map(t => (t[1] || '').split(' ')[1]).filter(Boolean));
const anzahl = menge => menge?.size ?? null;
const verengt = () => {
  const pfad = 'automation/lib/kategorien_verengt_daten.json';
  const zeilen = lies(pfad);
  if (zeilen === null) return null;
  try {
    const daten = JSON.parse(zeilen.join('\n'));
    return Array.isArray(daten) ? daten.length : unbekannt(pfad, 'JSON ist keine Liste');
  } catch { return unbekannt(pfad, 'ungültiges JSON'); }
};

const ausw = geschrieben('dropship/cj_varianten_ledger.txt');
const kandidatenpfad = '/tmp/auswahl_kandidaten.csv';
const kandidaten = lies(kandidatenpfad);
const kand = kandidaten === null ? null : kandidaten.some(z => !z.split(';')[0].trim())
  ? unbekannt(kandidatenpfad, 'Kandidat ohne Handle')
  : new Set(kandidaten.map(z => z.split(';')[0].trim()));
// Nachgezogene Produkte verschwinden aus neuen Scans. Nur mit beiden Quellen ist die Vereinigung bekannt.
const pool = kand !== null && ausw !== null ? new Set([...kand, ...ausw]) : null;

const zeilen = [
  { id: 'auswahl', bereich: 'Varianten-Auswahl nachgezogen', einheit: 'Produkte', fertig: anzahl(ausw), gesamt: anzahl(pool), quelle: 'cj_varianten_ledger.txt + Kandidatenliste vom Katalog-Scan', anmerkung: 'Arbeitsvorrat aus Kandidaten und belegten Schreib-Erfolgen, keine Katalogquote. Ein Teil führt bei CJ wirklich nur eine Variante; übersprungen und SKU_GESETZT zählen nicht als nachgezogene Auswahl' },
  { id: 'varbilder', bereich: 'Variantenbilder verknüpft', einheit: 'Produkte', fertig: anzahl(geschrieben('dropship/cj_variantenbilder_ledger.txt')), gesamt: 890, quelle: 'cj_variantenbilder_ledger.txt', anmerkung: 'Umfang gemessen am 25.10. an den neuesten 2010 CJ-Produkten' },
  { id: 'texte', bereich: 'Ausführliche Produkttexte', einheit: 'Produkte', fertig: anzahl(art('text-v2')), gesamt: null, quelle: 'kategorien_ledger.txt (text-v2)', anmerkung: 'nur Produkte mit lesbarem CJ-Datenblatt; Umfang nicht gemessen' },
  { id: 'fakten', bereich: 'Technische Daten, Lieferumfang', einheit: 'Produkte', fertig: anzahl(art('fakten')), gesamt: null, quelle: 'kategorien_ledger.txt (fakten)', anmerkung: 'nur belegte Angaben aus dem Datenblatt' },
  { id: 'labels', bereich: 'Kategorie-Bilder', einheit: 'Kategorien', fertig: anzahl(art('bild')), gesamt: 88, quelle: 'kategorien_ledger.txt (bild)', anmerkung: '88 Kategorien in lib/kategorien.mjs' },
  { id: 'bewertung', bereich: 'Gut bewertete zuerst', einheit: 'Kategorien', fertig: anzahl(art('bewertung-zuerst')), gesamt: null, quelle: 'kategorien_ledger.txt (bewertung-zuerst)', anmerkung: 'Kategorien im Menü mit mindestens 10 Produkten' },
  { id: 'optionen', bereich: 'Optionswerte ins Deutsche', einheit: 'Produkte', fertig: anzahl(art('optionen-uebersetzt')), gesamt: 2863, quelle: 'kategorien_ledger.txt (optionen-uebersetzt)', anmerkung: 'Umfang gemessen am 26.10. (2 863 Produkte mit englischen Werten); ein Teil bleibt bewusst englisch (Namenskollision, Zahl, Marke)' },
  { id: 'verengt', bereich: 'Menü-Seiten ohne Fremdprodukte', einheit: 'Kategorien', fertig: verengt(), gesamt: 27, quelle: 'lib/kategorien_verengt_daten.json (live am 26.10.)', anmerkung: '27 Alt-Collections von Titel-Regeln auf Tags mit Google-Kategorie-Ausschlüssen umgestellt; Prüfer-Ausreisser 631 → 315' },
  { id: 'titel', bereich: 'Titel korrigiert', einheit: 'Produkte', fertig: anzahl(art('titel')), gesamt: null, quelle: 'kategorien_ledger.txt (titel)', anmerkung: 'Titel, die dem Datenblatt widersprachen' },
].map(z => ({ ...z, stand: zeitpunkt }));
writeFileSync(OUT, JSON.stringify(zeilen, null, 1));
console.log(zeilen.map(z => `${z.bereich}: ${z.fertig ?? 'unbekannt'} / ${z.gesamt ?? 'unbekannt'}`).join('\n'));
