#!/usr/bin/env node
// Blackbox-Gegenproben: echte Berichtdatei, alle Datei-Zugriffe durch isolierte Attrappen ersetzt.
// Kein Shop, Netz, /tmp-Kandidatenbestand oder echtes Ledger wird gelesen/geschrieben.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const ziel = process.env.FORTSCHRITT_TEST_TARGET || fileURLToPath(new URL('./fortschritt_daten.mjs', import.meta.url));
const bootstrap = String.raw`
  import fs from 'node:fs';
  import { syncBuiltinESMExports } from 'node:module';
  const input = JSON.parse(fs.readFileSync(0, 'utf8'));
  const quelltext = fs.readFileSync(input.ziel, 'utf8');
  const ausgaben = {}, logs = [], warnungen = [];
  fs.existsSync = p => Object.hasOwn(input.dateien, p);
  fs.readFileSync = p => {
    const wert = input.dateien[p];
    if (!Object.hasOwn(input.dateien, p) || typeof wert !== 'string') {
      const e = new Error('Testquelle nicht lesbar'); e.code = wert?.code || 'ENOENT'; throw e;
    }
    return wert;
  };
  fs.writeFileSync = (p, inhalt) => { ausgaben[p] = inhalt; };
  syncBuiltinESMExports();
  console.log = (...s) => logs.push(s.join(' '));
  console.error = (...s) => warnungen.push(s.join(' '));
  process.env.OUT = '/virtuell/fortschritt.json';
  let fehler = null;
  try { await import('data:text/javascript;base64,' + Buffer.from(quelltext).toString('base64')); } catch (e) { fehler = e.message; }
  process.stdout.write(JSON.stringify({ zeilen: ausgaben[process.env.OUT] ? JSON.parse(ausgaben[process.env.OUT]) : null, logs, warnungen, fehler }));
`;
const ledger = 'dropship/cj_varianten_ledger.txt';
const kandidaten = '/tmp/auswahl_kandidaten.csv';
const bilder = 'dropship/cj_variantenbilder_ledger.txt';
const kategorien = 'dropship/kategorien_ledger.txt';
const verengt = 'automation/lib/kategorien_verengt_daten.json';
const zeit = '2026-10-28T10:00:00.000Z';
const zeile = (h, status, grund = 'Test') => `${h} · ${zeit} · ${status} · ${grund}`;
const grundlage = () => ({
  [ledger]: [zeile('fertig', 'GESCHRIEBEN'), zeile('fertig', 'GESCHRIEBEN'), zeile('solo', 'UEBERSPRUNGEN', 'CJ führt nur 1 Variante — kein Auswahlproblem'), zeile('sku', 'SKU_GESETZT'), zeile('fehler', 'FEHLER')].join('\n'),
  [kandidaten]: 'offen;1;CJ-123;3;123\nfertig;2;CJ-456;2;456\noffen;1;CJ-123;3;123\n',
  [bilder]: zeile('bild-a', 'GESCHRIEBEN'),
  [kategorien]: `${zeit} · text-v2 text-a\n${zeit} · text-v2 text-a\n${zeit} · optionen-uebersetzt text-b\n${zeit} · fakten text-c\n`,
  [verengt]: '[{"handle":"kategorie-a"}]',
});
function lauf(dateien) {
  const p = spawnSync(process.execPath, ['--input-type=module', '--eval', bootstrap], { input: JSON.stringify({ ziel, dateien }), encoding: 'utf8', timeout: 10000, env: { PATH: process.env.PATH } });
  assert.equal(p.status, 0, p.stderr || p.error?.message);
  const r = JSON.parse(p.stdout);
  assert.equal(r.fehler, null, r.fehler);
  assert.equal(r.zeilen.length, 9);
  return r;
}
const auswahl = r => r.zeilen.find(z => z.id === 'auswahl');
let ok = 0, fehler = 0;
function pruefe(name, test) { try { test(); ok++; console.log(`ok ${name}`); } catch (e) { fehler++; console.error(`FEHLER ${name}: ${e.message}`); } }

pruefe('Vereinigung zählt frühere Erfolge und aktuelle Kandidaten genau einmal', () => {
  const r = lauf(grundlage());
  assert.equal(auswahl(r).fertig, 1);
  assert.equal(auswahl(r).gesamt, 2);
  assert.equal(r.zeilen.find(z => z.id === 'texte').fertig, 1);
  assert.equal(r.zeilen.find(z => z.id === 'optionen').fertig, 1);
  assert.deepEqual(r.warnungen, []);
});
pruefe('Fehlende Kandidatenliste ergibt unbekannten Nenner statt falscher 100 %', () => {
  const d = grundlage(); delete d[kandidaten]; const r = lauf(d);
  assert.equal(auswahl(r).fertig, 1); assert.equal(auswahl(r).gesamt, null);
  assert.match(r.logs.join('\n'), /1 \/ unbekannt/);
  assert.match(r.warnungen.join('\n'), /auswahl_kandidaten.csv.*ENOENT/);
});
pruefe('Unlesbare Kandidaten sind unbekannt; übrige Bereiche bleiben messbar', () => {
  const d = grundlage(); d[kandidaten] = { code: 'EACCES' }; const r = lauf(d);
  assert.equal(auswahl(r).gesamt, null); assert.equal(r.zeilen.find(z => z.id === 'varbilder').fertig, 1);
  assert.match(r.warnungen.join('\n'), /EACCES/);
});
pruefe('Fehlendes Ledger ist kein Null-Erfolg und liefert keinen vollständigen Pool', () => {
  const d = grundlage(); delete d[ledger]; const r = lauf(d);
  assert.equal(auswahl(r).fertig, null); assert.equal(auswahl(r).gesamt, null);
});
pruefe('Leere vorhandene Quellen ergeben belegte Nullen', () => {
  const d = grundlage(); d[ledger] = ''; d[kandidaten] = '\n  \n'; const r = lauf(d);
  assert.equal(auswahl(r).fertig, 0); assert.equal(auswahl(r).gesamt, 0);
  assert.match(r.logs.join('\n'), /0 \/ 0/); assert.deepEqual(r.warnungen, []);
});
pruefe('Leerer neuer Scan erhält schon nachgezogene Produkte im Pool', () => {
  const d = grundlage(); d[kandidaten] = ''; const r = lauf(d);
  assert.equal(auswahl(r).fertig, 1); assert.equal(auswahl(r).gesamt, 1);
});
pruefe('SKU-Geändert, Einvarianten-Skip und Fehler sind kein Auswahl-Erfolg', () => {
  const d = grundlage(); d[ledger] = [zeile('solo', 'UEBERSPRUNGEN'), zeile('sku', 'SKU_GESETZT'), zeile('fehler', 'FEHLER')].join('\n'); const r = lauf(d);
  assert.equal(auswahl(r).fertig, 0); assert.equal(auswahl(r).gesamt, 2);
});
pruefe('Beschädigtes Ledger ergibt unbekannt statt Teilzählung', () => {
  const d = grundlage(); d[ledger] += '\nunvollständig'; const r = lauf(d);
  assert.equal(auswahl(r).fertig, null); assert.equal(auswahl(r).gesamt, null);
  assert.match(r.warnungen.join('\n'), /ungültige Ledger-Zeile/);
});
pruefe('Kandidat ohne Handle ergibt unbekannt statt Phantomprodukt', () => {
  const d = grundlage(); d[kandidaten] += ';1;CJ-999;1;999\n'; const r = lauf(d);
  assert.equal(auswahl(r).gesamt, null);
});
pruefe('Fehlende weitere Ledger bleiben unbekannt, Auswahl unverändert', () => {
  const d = grundlage(); delete d[bilder]; delete d[kategorien]; const r = lauf(d);
  for (const id of ['varbilder', 'texte', 'fakten', 'labels', 'bewertung', 'optionen', 'titel']) assert.equal(r.zeilen.find(z => z.id === id).fertig, null, id);
  assert.equal(auswahl(r).fertig, 1);
});
pruefe('Fehlende oder beschädigte JSON-Daten blockieren keine unabhängigen Zahlen', () => {
  for (const wert of [undefined, '{kaputt', '{}']) {
    const d = grundlage(); if (wert === undefined) delete d[verengt]; else d[verengt] = wert; const r = lauf(d);
    assert.equal(r.zeilen.find(z => z.id === 'verengt').fertig, null); assert.equal(auswahl(r).fertig, 1);
  }
});
pruefe('Anmerkung bezeichnet Arbeitsvorrat und keine Katalog-Vollständigkeit', () => {
  const a = auswahl(lauf(grundlage()));
  assert.match(a.anmerkung, /keine Katalogquote/);
  assert.match(a.anmerkung, /SKU_GESETZT zählen nicht/);
});

console.log(`${ok} ok, ${fehler} Fehler`);
process.exitCode = fehler ? 1 : 0;
